//! Official D&D lists (lineages, backgrounds, feats, gear, classes), built into the binary.
//! The JSON files in data/lists/ are generated by tools/fetch_lists.py.

use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};

use serde::Deserialize;

use crate::model::{at, ActionDef, Feature, ResourceDef, Toggle};

type Table = BTreeMap<u32, u32>;

// --- Lineages ----------------------------------------------------------------

#[derive(Deserialize, Clone)]
pub struct Choose { pub n: u32, pub amount: i32 }

#[derive(Deserialize, Clone, Default)]
pub struct Asi {
    #[serde(default)] pub fixed: BTreeMap<String, i32>,
    #[serde(default)] pub choose: Vec<Choose>,
}

#[derive(Deserialize, Clone, Default)]
#[serde(default)]
pub struct Section {
    pub asi: Option<Asi>,
    pub size: Option<String>,
    pub speed: Option<u32>,
    pub languages: Vec<String>,
    pub extra_languages: u32,
    pub skills: Vec<String>,
    pub extra_skills: u32,
    pub feats: u32,
    pub traits: Vec<Feature>,
}

#[derive(Deserialize)]
pub struct LineageSub {
    pub name: String,
    #[serde(default)] pub replaces: bool,
    #[serde(flatten)] pub sec: Section,
}

#[derive(Deserialize)]
pub struct Lineage {
    pub name: String,
    pub source: String,
    #[serde(flatten)] pub sec: Section,
    #[serde(default)] pub subs: Vec<LineageSub>,
}

/// What a lineage plus an optional subrace/variant actually gives.
#[derive(Default)]
pub struct Effective {
    pub fixed: BTreeMap<String, i32>,
    pub choose: Vec<Choose>,
    pub has_asi: bool,
    pub speed: Option<u32>,
    pub languages: Vec<String>,
    pub extra_languages: u32,
    pub skills: Vec<String>,
    pub extra_skills: u32,
    pub feats: u32,
    pub traits: Vec<Feature>,
}

impl Lineage {
    pub fn effective(&self, sub: Option<usize>) -> Effective {
        let base = &self.sec;
        let sub = sub.map(|i| &self.subs[i]);
        let mut e = Effective::default();
        let add = |asi: &Option<Asi>, e: &mut Effective| {
            if let Some(a) = asi {
                e.has_asi = true;
                for (k, v) in &a.fixed { *e.fixed.entry(k.clone()).or_insert(0) += v; }
                e.choose.extend(a.choose.iter().cloned());
            }
        };
        match sub {
            Some(s) if s.replaces && s.sec.asi.is_some() => add(&s.sec.asi, &mut e),
            Some(s) => { add(&base.asi, &mut e); add(&s.sec.asi, &mut e); }
            None => add(&base.asi, &mut e),
        }
        e.speed = sub.and_then(|s| s.sec.speed).or(base.speed);
        e.extra_languages = base.extra_languages + sub.map_or(0, |s| s.sec.extra_languages);
        e.extra_skills = base.extra_skills + sub.map_or(0, |s| s.sec.extra_skills);
        e.feats = base.feats + sub.map_or(0, |s| s.sec.feats);
        for sec in std::iter::once(base).chain(sub.map(|s| &s.sec)) {
            for l in &sec.languages { if !e.languages.contains(l) { e.languages.push(l.clone()); } }
            for sk in &sec.skills { if !e.skills.contains(sk) { e.skills.push(sk.clone()); } }
            for t in &sec.traits {
                match e.traits.iter_mut().find(|x| x.name == t.name) {
                    Some(x) => *x = t.clone(),
                    None => e.traits.push(t.clone()),
                }
            }
        }
        e
    }
}

// --- Backgrounds, feats, gear -----------------------------------------------------

#[derive(Deserialize)]
pub struct Background {
    pub name: String,
    pub source: String,
    #[serde(default)] pub skills: Vec<String>,
    #[serde(default)] pub extra_skills: u32,
    #[serde(default)] pub tools: String,
    #[serde(default)] pub extra_languages: u32,
    pub feature: Option<String>,
    #[serde(default)] pub url: String,
}

#[derive(Deserialize)]
pub struct FeatAsi { pub options: Vec<String>, pub amount: i32 }

/// A Wild Shape form from the SRD 5.1 (CC-BY-4.0): beast, or elemental for the Circle of the Moon.
#[derive(Deserialize)]
pub struct BeastDef {
    pub name: String,
    #[serde(default)] pub size: String,
    pub cr: f64,
    pub challenge: String,
    pub ac: i32,
    pub hp: i32,
    pub speed: BTreeMap<String, u32>,
    pub attacks: Vec<BeastAttack>,
    pub multiattack: Option<String>,
    pub elemental: bool,
}

#[derive(Deserialize)]
pub struct BeastAttack {
    pub name: String,
    pub hit: i32,
    pub dice: Option<(u32, u32)>, // None: fixed damage, all in bonus
    pub bonus: i32,
    #[serde(rename = "type")] pub kind: String,
}

/// A Metamagic option, Eldritch Invocation or Pact Boon.
#[derive(Deserialize)]
pub struct OptionDef {
    pub name: String,
    pub source: String,
    pub prereq: Option<String>,
    pub desc: String,
    #[serde(default)] pub url: String,
    pub action: Option<ActionDef>, // added to the action list when picked (an Elemental Discipline, Colossus Slayer)
}

pub fn options(kind: &str) -> &'static [OptionDef] {
    static C: OnceLock<BTreeMap<String, Vec<OptionDef>>> = OnceLock::new();
    let o = C.get_or_init(|| serde_json::from_str(include_str!("../data/lists/options.json")).expect("options.json"));
    o.get(kind).map_or(&[], |v| v.as_slice())
}

#[derive(Deserialize)]
pub struct FeatDef {
    pub name: String,
    pub source: String,
    pub prereq: Option<String>,
    pub asi: Option<FeatAsi>,
    #[serde(default)] pub min_ability: BTreeMap<String, i32>,
    #[serde(default)] pub desc: String,
    #[serde(default)] pub url: String,
}

#[derive(Deserialize)]
pub struct Weapon {
    pub name: String,
    pub dice: (u32, u32),
    #[serde(rename = "type")] pub dmg_type: String,
    pub props: String,
    pub ranged: bool,
    pub finesse: bool,
    pub two_handed: bool,
    pub thrown: Option<String>,
}

#[derive(Deserialize)]
pub struct Armor {
    pub name: String,
    pub category: String, // Light, Medium, Heavy, Shield
    pub ac: i32,
    pub dex: String,      // "full" | "max2" | "none"
}

// --- Spells ------------------------------------------------------------------------

#[derive(Deserialize)]
pub struct Spell {
    pub name: String,
    pub level: u32,
    pub school: String,
    pub source: String,
    pub time: String,
    pub range: String,
    pub comp: String,
    pub duration: String,
    pub ritual: bool,
    pub conc: bool,
    pub classes: Vec<String>,
    pub desc: String, // full text for SRD 5.1 spells, our summary for the others
    #[serde(default)] pub url: String,
    pub dmg: Option<(u32, u32, String)>,
    pub attack: bool,
    pub save: Option<String>,
    pub upcast: Option<(u32, u32)>, // extra dice per slot level above the spell's own
    pub scales: bool,               // cantrip damage grows at levels 5, 11, 17
    pub healing: bool,                // dmg then holds the healing dice
    #[serde(default)] pub heal_mod: bool,  // ...plus the spellcasting modifier
    #[serde(default)] pub flat: u32,       // flat bonus per hit (Magic Missile's +1)
    #[serde(default = "one")] pub count: u32, // darts / rays, each rolled on its own
    #[serde(default)] pub count_up: bool,  // one more per slot level above the spell's own
    #[serde(default)] pub beams: bool,     // cantrip that scales in beams, not dice (Eldritch Blast)
}

pub fn spell(name: &str) -> Option<&'static Spell> { spells().iter().find(|s| s.name.eq_ignore_ascii_case(name)) }

/// Spellcasting rules of a class (or of a subclass such as Eldritch Knight), read from the wikidot level table.
#[derive(Deserialize, Clone)]
pub struct Casting {
    pub ability: String,
    pub kind: String,                     // full | half | third | pact
    pub mode: String,                     // known | prepared | spellbook
    pub prepared: Option<String>,         // "mod+level" | "mod+half"
    pub list: String,                     // class whose spell list is used
    #[serde(default)] pub cantrips: Table,
    #[serde(default)] pub known: Table,
    #[serde(default)] pub slots: BTreeMap<u32, Vec<u32>>, // class level -> slots of level 1..9
    #[serde(default)] pub pact_slots: Table,
    #[serde(default)] pub pact_level: Table,
    #[serde(default)] pub schools: Vec<String>, // Eldritch Knight, Arcane Trickster: leveled spells from these schools...
    #[serde(default)] pub free_at: Vec<u32>,    // ...except one of any school gained at each of these class levels
}

impl Casting {
    pub fn slots_at(&self, class_level: u32, slot_level: usize) -> u32 {
        self.slots.get(&class_level).and_then(|v| v.get(slot_level - 1)).copied().unwrap_or(0)
    }
    /// The class-list spells among `names` keep to the schools, but for the free ones gained by `class_level`.
    pub fn schools_ok(&self, class_level: u32, names: &[String]) -> bool {
        if self.schools.is_empty() { return true; }
        let free = self.free_at.iter().filter(|&&l| l <= class_level).count();
        names.iter().filter_map(|n| spell(n)).filter(|s| s.level > 0 && s.classes.contains(&self.list) && !self.schools.contains(&s.school)).count() <= free
    }

    /// "abjuration or evocation, 1 of any school": the rule for a spell menu title, empty without one.
    pub fn schools_hint(&self, class_level: u32) -> String {
        if self.schools.is_empty() { return String::new(); }
        let free = self.free_at.iter().filter(|&&l| l <= class_level).count();
        format!(" ({}; {free} of any school)", self.schools.join(" or ").to_lowercase())
    }

    /// Highest spell level castable at this class level.
    pub fn top_level(&self, class_level: u32) -> u32 {
        if self.kind == "pact" { return at(&self.pact_level, class_level); }
        (1..=9).rev().find(|&l| self.slots_at(class_level, l as usize) > 0).unwrap_or(0)
    }
}

// --- Classes -------------------------------------------------------------------------

#[derive(Deserialize)]
pub struct SkillChoice { pub choose: usize, pub from: Vec<String> }

#[derive(Deserialize)]
pub struct Style {
    pub name: String,
    pub desc: String,
    pub effect: Option<String>,
}

#[derive(Deserialize)]
pub struct Subclass {
    pub name: String,
    pub source: String,
    #[serde(default)] pub resources: Vec<ResourceDef>,
    #[serde(default)] pub actions: Vec<ActionDef>,
    #[serde(default)] pub toggles: Vec<Toggle>,
    #[serde(default)] pub skills: usize, // skill proficiencies of your choice (Lore)
    #[serde(default)] pub attacks_per_action: Table, // Extra Attack of a subclass (Valor), replaces the class's
    #[serde(default)] pub options: BTreeMap<String, Table>, // options known by level, like the class's (Elemental Disciplines)
    pub maneuver_pool: Option<String>,
    #[serde(default)] pub tables: BTreeMap<String, Table>,
    #[serde(default)] pub dice: BTreeMap<String, Table>,
    #[serde(default)] pub maneuvers_known: Table,
    #[serde(default)] pub features: BTreeMap<u32, Vec<Feature>>,
    pub casting: Option<Casting>,
    #[serde(default)] pub always: BTreeMap<u32, Vec<String>>,   // domain / oath / circle spells, by class level
    #[serde(default)] pub expanded: BTreeMap<u32, Vec<String>>, // warlock patron spells added to the list, by spell level
}

/// Unarmored Defense: AC is 10 + DEX + `ability` while no armor is worn.
#[derive(Deserialize)]
pub struct Unarmored { pub ability: String, pub shield: bool }

#[derive(Deserialize)]
pub struct ClassData {
    pub name: String,
    pub hit_die: u32,
    pub saves: Vec<String>,
    pub skills: SkillChoice,
    pub armor: Vec<String>,
    pub weapons: Vec<String>,
    #[serde(default)] pub tools: Vec<String>,
    pub asi_levels: Vec<u32>,
    pub subclass_level: u32,
    pub subclass_title: String,
    pub attacks_per_action: Table,
    #[serde(default)] pub resources: Vec<ResourceDef>,
    #[serde(default)] pub tables: BTreeMap<String, Table>,
    #[serde(default)] pub actions: Vec<ActionDef>,
    #[serde(default)] pub toggles: Vec<Toggle>,
    pub unarmored: Option<Unarmored>,
    pub casting: Option<Casting>,
    #[serde(default)] pub dice: BTreeMap<String, Table>,
    #[serde(default = "one")] pub style_level: u32, // level that grants a fighting style
    #[serde(default)] pub expertise: Vec<u32>, // levels that grant two skills with double proficiency
    pub features: BTreeMap<u32, Vec<Feature>>,
    #[serde(default)] pub styles: Vec<Style>,
    #[serde(default)] pub options: BTreeMap<String, Table>, // option kind -> how many known by class level
    pub subclasses: Vec<Subclass>,
}

/// Level tables of a class merged with its subclass: what a level up looks at.
pub struct Progression {
    pub asi_levels: Vec<u32>,
    pub resources: BTreeMap<String, Table>,
    pub dice: BTreeMap<String, Table>,
    pub maneuvers_known: Table,
    pub attacks_per_action: Table,
    pub features: BTreeMap<u32, Vec<Feature>>,
}

fn one() -> u32 { 1 }

macro_rules! list {
    ($name:ident, $ty:ty, $file:literal) => {
        pub fn $name() -> &'static Vec<$ty> {
            static C: OnceLock<Vec<$ty>> = OnceLock::new();
            C.get_or_init(|| serde_json::from_str(include_str!(concat!("../data/lists/", $file))).expect($file))
        }
    };
}

list!(lineages, Lineage, "lineages.json");
list!(backgrounds, Background, "backgrounds.json");
list!(feats, FeatDef, "feats.json");
list!(weapons, Weapon, "weapons.json");
list!(armors, Armor, "armor.json");
list!(spells, Spell, "spells.json");
list!(beasts, BeastDef, "beasts.json");

pub fn classes() -> &'static Vec<ClassData> {
    static C: OnceLock<Vec<ClassData>> = OnceLock::new();
    C.get_or_init(|| {
        [include_str!("../data/lists/classes/fighter.json"), include_str!("../data/lists/classes/barbarian.json"),
         include_str!("../data/lists/classes/wizard.json"), include_str!("../data/lists/classes/cleric.json"), include_str!("../data/lists/classes/druid.json"),
         include_str!("../data/lists/classes/bard.json"), include_str!("../data/lists/classes/sorcerer.json"), include_str!("../data/lists/classes/warlock.json"),
         include_str!("../data/lists/classes/rogue.json"),
         include_str!("../data/lists/classes/monk.json"),
         include_str!("../data/lists/classes/paladin.json"), include_str!("../data/lists/classes/ranger.json")]
            .iter().map(|j| serde_json::from_str(j).expect("class json")).collect()
    })
}

pub fn class_data(name: &str) -> Option<&'static ClassData> { classes().iter().find(|c| c.name == name) }

pub fn progression(class: &str, sub: Option<&str>) -> Option<&'static Progression> {
    static CACHE: Mutex<BTreeMap<String, &'static Progression>> = Mutex::new(BTreeMap::new());
    let key = format!("{class}/{}", sub.unwrap_or(""));
    let mut cache = CACHE.lock().unwrap();
    if let Some(p) = cache.get(&key) { return Some(*p); }
    let cd = class_data(class)?;
    let sd = sub.and_then(|s| cd.subclasses.iter().find(|x| x.name == s));
    let mut p = Progression {
        asi_levels: cd.asi_levels.clone(),
        resources: cd.tables.clone(),
        dice: cd.dice.clone(),
        maneuvers_known: Table::new(),
        attacks_per_action: cd.attacks_per_action.clone(),
        features: cd.features.clone(),
    };
    if let Some(sd) = sd {
        p.resources.extend(sd.tables.clone());
        p.dice.extend(sd.dice.clone());
        p.maneuvers_known = sd.maneuvers_known.clone();
        if !sd.attacks_per_action.is_empty() { p.attacks_per_action = sd.attacks_per_action.clone(); }
        for (lvl, fs) in &sd.features { p.features.entry(*lvl).or_default().extend(fs.iter().cloned()); }
    }
    let leaked: &'static Progression = Box::leak(Box::new(p));
    cache.insert(key, leaked);
    Some(leaked)
}

fn split_prog(prog: &str) -> (&str, Option<&str>) {
    prog.split_once('/').map_or((prog, None), |(c, s)| (c, Some(s)))
}

/// Casting rules for a "Class/Subclass" progression: the subclass's own (Eldritch Knight) or the class's.
pub fn casting_of(prog: &str) -> Option<&'static Casting> {
    let (class, sub) = split_prog(prog);
    let cd = class_data(class)?;
    sub.and_then(|s| cd.subclasses.iter().find(|x| x.name == s)).and_then(|s| s.casting.as_ref()).or(cd.casting.as_ref())
}

fn sub_of(prog: &str) -> Option<&'static Subclass> {
    let (class, sub) = split_prog(prog);
    class_data(class)?.subclasses.iter().find(|x| Some(x.name.as_str()) == sub)
}

/// Domain / oath / circle spells that are always prepared at this class level.
pub fn always_spells(prog: &str, level: u32) -> Vec<String> {
    sub_of(prog).map(|s| s.always.range(..=level).flat_map(|(_, v)| v.clone()).collect()).unwrap_or_default()
}

/// Patron spells added to a warlock's list, up to this spell level.
pub fn expanded_spells(prog: &str, top: u32) -> Vec<String> {
    sub_of(prog).map(|s| s.expanded.range(..=top).flat_map(|(_, v)| v.clone()).collect()).unwrap_or_default()
}

/// Spells a character with this casting can learn or prepare: its list, up to `top`, cantrips when `top` is 0.
pub fn spell_choices(c: &Casting, prog: &str, level: u32, cantrips: bool) -> Vec<&'static Spell> {
    let top = c.top_level(level);
    let extra = expanded_spells(prog, top);
    spells().iter()
        .filter(|s| if cantrips { s.level == 0 } else { s.level >= 1 && s.level <= top })
        .filter(|s| s.classes.contains(&c.list) || extra.contains(&s.name))
        .collect()
}

/// Short book names for menus.
pub fn abbr(source: &str) -> String {
    const SHORT: [(&str, &str); 14] = [
        ("Player's Handbook", "PHB"), ("Xanathar's Guide to Everything", "XGtE"), ("Tasha's Cauldron of Everything", "TCoE"),
        ("Volo's Guide to Monsters", "VGtM"), ("Mordenkainen Presents: Monsters of the Multiverse", "MotM"),
        ("Mordenkainen's Tome of Foes", "MToF"), ("Sword Coast Adventurer's Guide", "SCAG"),
        ("Explorer's Guide to Wildemount", "EGtW"), ("Guildmaster's Guide to Ravnica", "GGtR"),
        ("Mythic Odysseys of Theros", "MOoT"), ("Fizban's Treasury of Dragons", "FToD"), ("Van Richten's Guide to Ravenloft", "VRGtR"),
        ("Elemental Evil Player's Companion", "EEPC"), ("Eberron - Rising from the Last War", "ERLW"),
    ];
    SHORT.iter().find(|(l, _)| *l == source).map_or_else(|| source.chars().take(28).collect::<String>().trim_end_matches(['/', ' ']).to_string(), |(_, s)| s.to_string())
}
